import sys

def is_k_lucky(ticket, k):
    def evaluate_expression(expr):
        try:
            return eval(expr)
        except ZeroDivisionError:
            return None

    def generate_expressions(prefix, remaining):
        if not remaining:
            return [prefix]
        expressions = []
        for i in range(1, len(remaining) + 1):
            next_prefix = prefix + remaining[:i]
            for expr in generate_expressions(next_prefix, remaining[i:]):
                expressions.append(expr)
            for op in ['+', '-', '*']:
                for expr in generate_expressions(op + remaining[:i], remaining[i:]):
                    expressions.append(prefix + expr)
        return expressions

    expressions = generate_expressions('', ticket)
    return any(evaluate_expression(expr) == k for expr in expressions)

def main():
    import sys
    k, m = map(int, sys.stdin.read().strip().split())
    tickets = set()
    num = 0
    while len(tickets) < m:
        ticket = f"{num:08d}"
        if is_k_lucky(ticket, k):
            tickets.add(ticket)
        num += 1
    for ticket in tickets:
        print(ticket)

main()
